// Преобразуем массив в объект для быстрого доступа по id
const LEVELS = {};
for (const level of LEVELS_ARRAY) {
    LEVELS[level.id] = level;
}

function getLevelData(levelId) {
    return LEVELS[levelId] ? JSON.parse(JSON.stringify(LEVELS[levelId])) : null;
}

function getAllLevels() {
    return Object.values(LEVELS);
}

function getAllLevelIds() {
    return Object.keys(LEVELS).sort();
}